const R_W = 124.06;
const R_H = 134.26;

/** The "R" mark alone (viewBox 124.06 × 134.26). Fill follows `color`. */
function RemocnR({ height, color }: { height: number; color: string }) {
  return (
    <svg
      viewBox={`0 0 ${R_W} ${R_H}`}
      height={height}
      width={(height * R_W) / R_H}
      style={{ display: "block" }}
      aria-hidden
    >
      <path fill={color} d={REMOCN_R_PATH} />
    </svg>
  );
}

interface ReplayWipeProps {
  /** The shot before the first wipe (and after every second one). Defaults to a "Live" broadcast frame. */
  from?: React.ReactNode;
  /** The shot after the first wipe. Defaults to a slow-mo "Replay" frame. */
  to?: React.ReactNode;
  /** Frames where a wipe starts. Shots alternate from → to → from… */
  wipeAt?: number[];
  /** Frames the R takes to cross the frame. 15–20 reads as a stinger. */
  wipeLength?: number;
  /** Big word in the default "Live" shot. */
  liveLabel?: string;
  /** Big word in the default "Replay" shot. */
  replayLabel?: string;
  /** Tag next to the Replay bug in the default "Replay" shot. */
  slowMoLabel?: string;
  /** The live marker in the default "Live" shot. */
  accent?: string;
  /** Color of the big word in the default "Live" shot; overrides the theme. */
  ink?: string;
  /** Stage and "Live" shot fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the default shots. Load it yourself; Barlow Condensed by default. */
  fontFamily?: string;
  /** Replaces the remocn R that spins across on the streak. */
  logo?: React.ReactNode;
  /** Size of the default shots' type and bugs, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps, speed 1, defaults):
//   0–26    "Live" shot: huge type pans slowly, the clock bug ticks
//  26–44    stinger: the remocn R spins across on the head of a "fluted"
//           gradient streak; the streak's slanted head wipes Live → Replay,
//           speed lines run with it, a flash + camera kick at mid-frame
//  44–84    "Replay" shot in slow motion on the gradient ground
//  84–102   the same stinger back to Live
// 102–      Live holds
const SWEEP = Easing.bezier(0.55, 0, 0.4, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "fluted": bg #050507, #1d2a8f, #2f7bff, #ff7a3d, #ffe2c4.
const FLUTED = ["#1D2A8F", "#2F7BFF", "#FF7A3D", "#FFE2C4"] as const;

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    dim: "#86858C",
    tab: "#1C1C20",
    tabInk: "#F3F2EF",
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    tab: "#121214",
    tabInk: "#F5F4F0",
  },
} as const;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

type ShotLook = {
  fontFamily: string;
  scale: number;
  delay: number;
  speed: number;
};

/** A short hit: up in 2 frames, eases back over 9. */
function kick(d: number) {
  if (d < 0) return 0;
  if (d < 2) return d / 2;
  const k = Math.max(0, 1 - (d - 2) / 9);
  return k * k;
}

function LiveShot({
  theme,
  accent,
  label,
  ink,
  stage,
  look: { fontFamily, scale, delay, speed },
}: {
  theme: "dark" | "light";
  accent: string;
  label: string;
  ink?: string;
  stage?: string;
  look: ShotLook;
}) {
  const t = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const u = Math.min(W / 1280, H / 720);
  const pan = interpolate(t, [0, 150], [0.025 * W, -0.025 * W], CLAMP);
  const secs = 12 + Math.floor(t / 30);
  const clock = `89:${String(secs % 60).padStart(2, "0")}`;
  return (
    <AbsoluteFill style={{ background: stage ?? c.stage }}>
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transform: `translateX(${pan}px)`,
            fontFamily,
            fontWeight: 500,
            fontSize: 640 * u,
            lineHeight: 1,
